}

def overlaps(s1, e1, s2, e2):
    return s1 < e2 and s2 < e1

def feasible(start):
    end = start + DURATION
    if start < WORK_START or end > WORK_END:
        return False
    for intervals in busy.values():
        for bs, be in intervals:
            if overlaps(start, end, bs, be):
                return False
    return True

CUTOFF = 12 * 60 + 30
# Preference: avoid a meeting that occurs after 12:30. A meeting that ends at 12:30 is preferred
# over one that starts at 12:30; among preferred slots, choose earliest.
best = None
for start in range(WORK_START, WORK_END - DURATION + 1):
    if not feasible(start):
        continue
    end = start + DURATION
    score = 0 if end <= CUTOFF else (1 if start <= CUTOFF else 2)
    if best is None:
        best = (score, start, end)
    else:
        if (score, start) < (best[0], best[1]):
            best = (score, start, end)

assert best is not None
_, start, end = best

